videoCategories = ["All", ...new Set(videos.map(v =&gt; v.category).filter(Boolean))].sort()







viewof videoCategoryFilter = {
  const container = html`&lt;div class="fs-filters"&gt;&lt;/div&gt;`;
  container.value = "All";

  function draw() {
    container.innerHTML = "";
    videoCategories.forEach(cat =&gt; {
      const isActive = cat === container.value;
      const color = cat === "All" ? "#2c7be5" : categoryColor(cat);
      const pill = html`&lt;button type="button" class="fs-filter-pill${isActive ? " active" : ""}"&gt;${cat}&lt;/button&gt;`;
      if (isActive) {
        pill.style.background = color;
        pill.style.borderColor = color;
      }
      pill.onclick = () =&gt; {
        container.value = cat;
        container.dispatchEvent(new CustomEvent("input"));
        draw();
      };
      container.appendChild(pill);
    });
  }
  draw();
  return container;
}







